import React from 'react';
import {
  ArrowUpRight,
  Briefcase,
  Building2,
  CalendarDays,
  FileBarChart2,
  FileText,
  Hand,
  LayoutDashboard,
  LogOut,
  ShieldCheck,
  Users,
  UserCircle,
  FolderCog,
} from 'lucide-react';

const Sidebar = ({ isOpen, isCollapsed, onClose, onToggleCollapse, canApprove, onOpenChat, currentUser }) => {
  const role = currentUser?.role || 'employee';
  const isManager = role === 'manager' || role === 'hr_admin' || currentUser?.is_superuser;
  const isAdmin = role === 'hr_admin' || currentUser?.is_superuser;

  const mainItems = [
    { label: 'Dashboard', icon: LayoutDashboard, section: 'dashboard', badge: null },
    { label: 'Apply Leave', icon: CalendarDays, section: 'apply-leave', badge: null },
    { label: 'My Leave', icon: FileText, section: 'my-leave', badge: null },
    { label: 'History', icon: FileBarChart2, section: 'history', badge: null },
    { label: 'Delegations', icon: Hand, section: 'delegations', badge: 2 },
  ];

  const teamItems = [
    { label: 'Approvals', icon: ShieldCheck, section: 'approvals', badge: 3 },
    { label: 'Team Calendar', icon: CalendarDays, section: 'team-calendar', badge: null },
    { label: 'Reports', icon: ArrowUpRight, section: 'reports', badge: null },
  ];

  const adminItems = [
    { label: 'Users', icon: Users, section: 'users', badge: null },
    { label: 'Departments', icon: Building2, section: 'departments', badge: null },
    { label: 'Leave Types', icon: Briefcase, section: 'leave-types', badge: null },
    { label: 'Audit Log', icon: FileText, section: 'audit-log', badge: null },
    { label: 'System Health', icon: FolderCog, section: 'system-health', badge: 'Live' },
  ];

  const accountItems = [
    { label: 'Profile', icon: UserCircle, section: 'profile', badge: null },
    { label: 'Sign out', icon: LogOut, section: 'logout', badge: null },
  ];

  const renderMenu = (items, activeSection = 'dashboard') => items.map(({ label, icon: Icon, section, badge }) => (
    <button
      key={section}
      className={`sidebar-link ${activeSection === section ? 'active' : ''}`}
      data-section={section}
      type="button"
      onClick={() => {
        if (typeof onOpenChat === 'function' && section === 'chat') onOpenChat();
        onClose && onClose();
      }}
    >
      <Icon size={16} aria-hidden="true" />
      <span>{label}</span>
      {badge ? <span className="sidebar-badge">{badge}</span> : null}
    </button>
  ));

  return (
    <>
      <button className={`shell-backdrop ${isOpen ? 'visible' : ''}`} aria-label="Close navigation" onClick={onClose} />
      <aside className={`app-sidebar ${isOpen ? 'open' : ''} ${isCollapsed ? 'collapsed' : ''}`} aria-label="Primary navigation">
        <div className="sidebar-brand">
          <button className="sidebar-collapse-toggle" type="button" onClick={onToggleCollapse} aria-label="Toggle sidebar">
            <span>◀</span>
          </button>
          <div className="brand-mark">
            <span className="brand-word brand-word-main">OKOA</span>
            <span className="brand-word brand-word-alt">FLOAT</span>
          </div>
        </div>

        <div className="sidebar-user-card">
          <div className="avatar-mini">{(currentUser?.name || 'J').charAt(0).toUpperCase()}</div>
          {!isCollapsed && (
            <div className="user-mini-meta">
              <div className="user-mini-name">{currentUser?.name || 'John Doe'}</div>
              <span className="role-pill">{currentUser?.role || 'employee'}</span>
            </div>
          )}
        </div>

        <nav className="sidebar-nav" aria-label="Sidebar navigation">
          {!isCollapsed && <div className="nav-label">MAIN</div>}
          {renderMenu(mainItems, 'dashboard')}

          {(isManager || canApprove) && (
            <>
              {!isCollapsed && <div className="nav-label">TEAM</div>}
              {renderMenu(teamItems, 'dashboard')}
            </>
          )}

          {isAdmin && (
            <>
              {!isCollapsed && <div className="nav-label">ADMIN</div>}
              {renderMenu(adminItems, 'dashboard')}
            </>
          )}

          {!isCollapsed && <div className="nav-label">ACCOUNT</div>}
          {renderMenu(accountItems, 'dashboard')}
        </nav>
      </aside>
    </>
  );
};

export default Sidebar;
